        require(address(this).balance >= deposit + withdrawAttempt);

        uint testBalanceBeforeDeposit = c.getBalance(address(this));
        c.addToBalance{value: deposit}();
        require(c.getBalance(address(this)) == testBalanceBeforeDeposit + deposit);

        uint beforeBalance = c.getBalance(address(this));
